-- China deep-dive page translations: page fields, stats, cards,
-- lifecycle card + statuses, steps, portal.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Compensación centralizada (Sistema de Impuestos de Oro)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Los calendarios regionales de eliminación del papel, los criterios de cuotas y los detalles de despliegue específicos por sector continúan evolucionando — confirme los requisitos actuales directamente con su sucursal local de la STA antes de construir una integración.', 'La reforma de la e-fapiao en China ha durado una década completa antes de alcanzar el estatus nacional — se trata de un sistema maduro y cuidadosamente probado, no de un despliegue apresurado.', 'La distinción crítica que hay que interiorizar: el XML es el documento legalmente vinculante. Todo lo demás — OFD, PDF — existe únicamente para la vista humana.', 'Un modelo de compensación de manual: nada es una factura legalmente válida en China hasta que la STA la ha validado y sellado.', 'El acceso se realiza a través de una cuenta fiscal digital en lugar de un único evento de "registro" — prepárese para una relación continua con la plataforma, no para una alta única.', 'China integra la aplicación de la ley en su arquitectura más amplia de administración tributaria en lugar de publicar un régimen de sanciones de facturación electrónica independiente.' FROM countries WHERE name_en = 'China';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Zentrales Clearing-Modell (Golden Tax System)', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Regionale Zeitpläne für den Papierausstieg, Quotenkriterien und sektorspezifische Rollout-Details entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt bei Ihrer lokalen STA-Niederlassung, bevor Sie eine Integration aufbauen.', 'Chinas E-Fapiao-Reform lief ein volles Jahrzehnt, bevor sie landesweiten Status erreichte — dies ist ein ausgereiftes, sorgfältig pilotiertes System, kein überstürzter Rollout.', 'Die entscheidende Unterscheidung, die es zu verinnerlichen gilt: Das XML ist das rechtsverbindliche Dokument. Alles andere — OFD, PDF — existiert rein für das menschliche Auge.', 'Ein lehrbuchmäßiges Clearing-Modell: In China ist nichts eine rechtsgültige Rechnung, bis die STA sie validiert und gestempelt hat.', 'Der Zugang erfolgt über ein digitales Steuerkonto statt über ein einziges "Registrierungsereignis" — rechnen Sie mit einer fortlaufenden Beziehung zur Plattform, nicht mit einer einmaligen Anmeldung.', 'China integriert die Durchsetzung in seine umfassendere Steuerverwaltungsarchitektur, anstatt ein eigenständiges Bußgeldregime für die E-Rechnung zu veröffentlichen.' FROM countries WHERE name_en = 'China';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Contrôle centralisé (Golden Tax System)', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les calendriers régionaux d''abandon du papier, les critères de quotas et les détails de déploiement sectoriels continuent d''évoluer — confirmez les exigences actuelles directement auprès de votre antenne locale de la STA avant de construire une intégration.', 'La réforme de la e-fapiao en Chine s''est étalée sur une décennie complète avant d''atteindre le statut national — il s''agit d''un système mature, soigneusement pilote, et non d''un déploiement précipité.', 'La distinction essentielle à retenir : le XML est le document juridiquement contraignant. Tout le reste — OFD, PDF — n''existe que pour l''œil humain.', 'Un modèle de contrôle conforme au manuel : rien n''est une facture juridiquement valable en Chine tant que la STA ne l''a pas validée et estampillée.', 'L''accès passe par un compte fiscal numérique plutôt que par un unique événement d''« inscription » — attendez-vous à une relation continue avec la plateforme, pas à une inscription ponctuelle.', 'La Chine intègre l''application des règles dans son architecture plus large d''administration fiscale plutôt que de publier un régime de sanctions distinct pour la facturation électronique.' FROM countries WHERE name_en = 'China';

