INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Fuente legal de verdad', '[["Formato", "XML estructurado"], ["Renderizado legible por humanos", "OFD (Open Fixed-layout Document) o PDF"], ["Peso legal", "Solo el XML — el OFD/PDF es solo para visualización"]]', 'La e-fapiao totalmente digitalizada específicamente no requiere un formato digital concreto para su validez legal — a diferencia de la antigua e-fapiao de IVA "no totalmente digital", que debía estar en OFD o PDF.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Rechtliche Quelle der Wahrheit', '[["Format", "Strukturiertes XML"], ["Menschenlesbare Darstellung", "OFD (Open Fixed-layout Document) oder PDF"], ["Rechtliches Gewicht", "Nur XML — OFD/PDF dient nur zur Anzeige"]]', 'Vollständig digitalisierte E-Fapiao erfordern für die Rechtsgültigkeit ausdrücklich kein bestimmtes digitales Format — anders als die ältere "nicht vollständig digitale" Umsatzsteuer-E-Fapiao, die in OFD oder PDF vorliegen musste.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Source légale de vérité', '[["Format", "XML structuré"], ["Rendu lisible par l''humain", "OFD (Open Fixed-layout Document) ou PDF"], ["Poids juridique", "XML uniquement — l''OFD/PDF sert uniquement à l''affichage"]]', 'La e-fapiao entièrement numérisée ne nécessite spécifiquement aucun format numérique particulier pour sa validité légale — contrairement à l''ancienne e-fapiao de TVA « non entièrement numérique », qui devait être au format OFD ou PDF.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Identificación de la factura', '[["Código de factura", "Número único de 20 dígitos"], ["Estructura", "Últimos 2 dígitos del año + código regional provincial + dígito del canal de emisión + código secuencial"], ["Añadido por", "La STA en el momento de la compensación, junto con un código QR"]]', 'Esta numeración estructurada es deliberadamente descodificable — la región y el canal de emisión están incrustados directamente en el propio código de factura.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Rechnungsidentifikation', '[["Rechnungscode", "Eindeutige 20-stellige Nummer"], ["Struktur", "Letzte 2 Ziffern des Jahres + Provinzregionalcode + Ausstellungskanal-Ziffer + fortlaufender Code"], ["Hinzugefügt von", "STA beim Clearing, zusammen mit einem QR-Code"]]', 'Diese strukturierte Nummerierung ist bewusst dekodierbar — Region und Ausstellungskanal sind direkt im Rechnungscode selbst enthalten.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Identification de la facture', '[["Code de facture", "Numéro unique à 20 chiffres"], ["Structure", "2 derniers chiffres de l''année + code régional provincial + chiffre du canal d''émission + code séquentiel"], ["Ajouté par", "La STA lors du contrôle, avec un code QR"]]', 'Cette numérotation structurée est délibérément décodable — la région et le canal d''émission sont directement intégrés dans le code de facture lui-même.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Cuotas de facturación', '[["Qué es", "Un límite al número de facturas que un contribuyente puede emitir"], ["Determinado por", "Nivel de riesgo fiscal, calificación crediticia fiscal, operaciones comerciales reales"], ["Ajuste", "Dinámico, basado en el comportamiento continuo"]]', 'Se trata de un mecanismo genuinamente distintivo — su propia capacidad de facturación está vinculada a su posición ante la autoridad fiscal, funcionando como un incentivo práctico de cumplimiento más allá de cualquier sanción formal.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Rechnungskontingente', '[["Was es ist", "Eine Obergrenze für die Anzahl der Rechnungen, die ein Steuerpflichtiger ausstellen kann"], ["Bestimmt durch", "Steuerrisikostufe, Steuerkredit-Bewertung, tatsächliche Geschäftstätigkeit"], ["Anpassung", "Dynamisch, basierend auf laufendem Verhalten"]]', 'Dies ist ein wirklich charakteristischer Mechanismus — Ihre Rechnungsstellungskapazität selbst ist an Ihr Ansehen bei der Steuerbehörde gekoppelt und wirkt als praktischer Compliance-Anreiz über jede formale Strafe hinaus.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Quotas de facturation', '[["Ce que c''est", "Un plafond sur le nombre de factures qu''un contribuable peut émettre"], ["Déterminé par", "Le niveau de risque fiscal, la cote de crédit fiscal, l''activité commerciale réelle"], ["Ajustement", "Dynamique, basé sur le comportement en cours"]]', 'Il s''agit d''un mécanisme véritablement distinctif — votre capacité de facturation elle-même est liée à votre réputation auprès de l''administration fiscale, agissant comme une incitation pratique à la conformité au-delà de toute sanction formelle.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Archivo', '[["Conservación estándar", "10 años"], ["Ciertas categorías de comprobantes", "Hasta 30 años"], ["Qué conservar", "XML compensado más código QR, código/número de factura, firma digital"]]', 'Confirme qué nivel de conservación se aplica a su categoría específica de comprobante — la diferencia entre 10 y 30 años es lo suficientemente significativa como para importar en el diseño del sistema de archivo.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Archivierung', '[["Standardaufbewahrung", "10 Jahre"], ["Bestimmte Belegkategorien", "Bis zu 30 Jahre"], ["Was aufzubewahren ist", "Cleared XML plus QR-Code, Rechnungscode/-nummer, digitale Signatur"]]', 'Bestätigen Sie, welche Aufbewahrungsstufe für Ihre spezifische Belegkategorie gilt — der Unterschied zwischen 10 und 30 Jahren ist erheblich genug, um für die Gestaltung des Archivierungssystems relevant zu sein.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Archivage', '[["Conservation standard", "10 ans"], ["Certaines catégories de pièces justificatives", "Jusqu''à 30 ans"], ["Ce qu''il faut conserver", "XML contrôlé plus code QR, code/numéro de facture, signature numérique"]]', 'Vérifiez quel niveau de conservation s''applique à votre catégorie de pièce justificative spécifique — l''écart entre 10 et 30 ans est suffisamment important pour compter dans la conception du système d''archivage.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Entrega al destinatario', '[["Canales", "Cuenta fiscal digital, correo electrónico, enlace de plataforma, código QR u otro medio acordado"], ["Sin método fijo", "La e-fapiao totalmente digitalizada permite una entrega flexible"]]', 'Esta flexibilidad es una mejora deliberada respecto al régimen anterior — reduce los costes de entrega y la fricción administrativa en comparación con exigir un traspaso fijo en OFD/PDF.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Zustellung an den Empfänger', '[["Kanäle", "Digitales Steuerkonto, E-Mail, Plattformlink, QR-Code oder andere vereinbarte Mittel"], ["Keine feste Methode", "Vollständig digitalisierte E-Fapiao ermöglicht flexible Zustellung"]]', 'Diese Flexibilität ist eine bewusste Verbesserung gegenüber dem älteren Regime — sie reduziert Zustellkosten und administrative Reibung im Vergleich zu einer festen OFD-/PDF-Übergabe.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Livraison au destinataire', '[["Canaux", "Compte fiscal numérique, e-mail, lien de plateforme, code QR ou autre moyen convenu"], ["Aucune méthode fixe", "La e-fapiao entièrement numérisée permet une livraison flexible"]]', 'Cette flexibilité est une amélioration délibérée par rapport à l''ancien régime — elle réduit les coûts de livraison et les frictions administratives par rapport à l''exigence d''une remise fixe en OFD/PDF.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Cuentas fiscales digitales', '[["Quién tiene una", "Tanto el emisor como el receptor"], ["Qué muestra", "Todas las e-fapiao emitidas/recibidas, en tiempo real"], ["Visibilidad del emisor", "Puede rastrear si el receptor ha deducido el IVA"]]', 'Esta visibilidad mutua en tiempo real es inusual a nivel internacional — la mayoría de los sistemas de compensación no dan al emisor una visión continua de lo que el receptor hace con la factura después.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Digitale Steuerkonten', '[["Wer eines erhält", "Aussteller und Empfänger"], ["Was es zeigt", "Alle ausgestellten/empfangenen E-Fapiao, in Echtzeit"], ["Sichtbarkeit für den Aussteller", "Kann verfolgen, ob der Empfänger die Umsatzsteuer abgezogen hat"]]', 'Diese gegenseitige Echtzeit-Sichtbarkeit ist international ungewöhnlich — die meisten Clearing-Systeme geben dem Aussteller keinen fortlaufenden Einblick, was der Empfänger anschließend mit der Rechnung macht.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Comptes fiscaux numériques', '[["Qui en a un", "L''émetteur et le destinataire"], ["Ce qu''il affiche", "Toutes les e-fapiao émises/reçues, en temps réel"], ["Visibilité de l''émetteur", "Peut suivre si le destinataire a déduit la TVA"]]', 'Cette visibilité mutuelle en temps réel est inhabituelle à l''échelle internationale — la plupart des systèmes de contrôle ne donnent pas à l''émetteur une visibilité continue sur ce que le destinataire fait ensuite de la facture.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Alcance', '[["Tipos de transacción", "B2B, B2G y B2C"], ["Formatos heredados", "Se están eliminando progresivamente"]]', 'Las fapiao en papel están en una trayectoria de retirada genuina — compruebe el anuncio de transición específico de su región y sector en lugar de asumir una única fecha nacional para todos.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Anwendungsbereich', '[["Transaktionsarten", "B2B, B2G und B2C"], ["Veraltete Formate", "Werden schrittweise ausgemustert"]]', 'Papier-Fapiao befinden sich auf einem echten Auslaufpfad — prüfen Sie die Übergangsankündigung für Ihre spezifische Region und Ihren Sektor, statt von einem einzigen landesweiten Termin für alle auszugehen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Périmètre', '[["Types de transaction", "B2B, B2G et B2C"], ["Formats hérités", "Progressivement supprimés"]]', 'Les fapiao papier suivent une véritable trajectoire de retrait — vérifiez l''annonce de transition propre à votre région et à votre secteur plutôt que de présumer d''une seule date nationale pour tout le monde.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'es', 'El flujo de compensación', 'Cada factura pasa por la misma secuencia:', 'La plataforma nacional de la STA (construida sobre el Sistema de Impuestos de Oro) añade la confirmación de validación, el ID clave único y el código QR antes de que la factura pueda existir legalmente.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'China';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'de', 'Der Clearing-Ablauf', 'Jede Rechnung durchläuft dieselbe Abfolge:', 'Die nationale Plattform der STA (aufgebaut auf dem Golden-Tax-System) fügt die Validierungsbestätigung, die eindeutige Key-ID und den QR-Code hinzu, bevor die Rechnung rechtlich existieren kann.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'China';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'fr', 'Le flux de contrôle', 'Chaque facture suit la même séquence :', 'La plateforme nationale de la STA (construite sur le Golden Tax System) ajoute la confirmation de validation, l''identifiant clé unique et le code QR avant que la facture ne puisse exister légalement.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'China';

