INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🎫 Las cuotas como verdadera palanca de aplicación', NULL, NULL, 'En lugar de depender principalmente de multas, el sistema chino vincula su capacidad práctica de emitir facturas a su posición ante la autoridad fiscal — una empresa con un perfil de riesgo fiscal o calificación crediticia deficientes puede ver su capacidad de facturación directamente restringida.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🎫 Kontingente als eigentlicher Durchsetzungshebel', NULL, NULL, 'Statt sich in erster Linie auf Bußgelder zu verlassen, koppelt Chinas System Ihre praktische Fähigkeit, Rechnungen auszustellen, an Ihr Ansehen bei der Steuerbehörde — ein Unternehmen mit schlechtem Steuerrisikoprofil oder schlechter Kreditbewertung kann seine Rechnungsstellungskapazität direkt eingeschränkt sehen.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🎫 Les quotas comme véritable levier de mise en application', NULL, NULL, 'Plutôt que de s''appuyer principalement sur des amendes, le système chinois lie votre capacité pratique à émettre des factures à votre réputation auprès de l''administration fiscale — une entreprise avec un mauvais profil de risque fiscal ou une mauvaise cote de crédit peut voir sa capacité de facturation directement limitée.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '📜 La larga historia del Sistema de Impuestos de Oro', NULL, NULL, 'La e-fapiao se apoya sobre la tercera y cuarta generación del Sistema de Impuestos de Oro — se trata de una infraestructura en desarrollo continuo desde hace años, no de un sistema construido desde cero únicamente para la facturación electrónica.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '📜 Die lange Geschichte des Golden-Tax-Systems', NULL, NULL, 'E-Fapiao baut auf der dritten und vierten Generation des Golden-Tax-Systems auf — dies ist eine Infrastruktur, die seit Jahren kontinuierlich weiterentwickelt wird, kein von Grund auf allein für die E-Rechnung gebautes System.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '📜 La longue histoire du Golden Tax System', NULL, NULL, 'La e-fapiao s''appuie sur les troisième et quatrième générations du Golden Tax System — il s''agit d''une infrastructure en développement continu depuis des années, et non d''un système construit de toutes pièces uniquement pour la facturation électronique.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🧾 Todavía existen seis tipos de fapiao', NULL, NULL, 'La fapiao general de IVA, la fapiao especial de IVA y las versiones totalmente digitalizadas de cada una coexisten actualmente durante la transición en curso — confirme qué tipo se aplica a su categoría específica de transacción en lugar de asumir que ya se aplica un formato único unificado en todas partes.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🧾 Sechs Fapiao-Typen bestehen weiterhin', NULL, NULL, 'Allgemeine Umsatzsteuer-Fapiao, spezielle Umsatzsteuer-Fapiao sowie deren vollständig digitalisierte Versionen bestehen während des laufenden Übergangs derzeit nebeneinander — bestätigen Sie, welcher Typ für Ihre spezifische Transaktionskategorie gilt, statt anzunehmen, dass bereits überall ein einheitliches Format gilt.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🧾 Six types de fapiao existent encore', NULL, NULL, 'La fapiao générale de TVA, la fapiao spéciale de TVA et leurs versions entièrement numérisées coexistent actuellement pendant la transition en cours — confirmez quel type s''applique à votre catégorie de transaction spécifique plutôt que de présumer qu''un format unique unifié s''applique déjà partout.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '📊 Declaraciones fiscales precumplimentadas a la vista', NULL, NULL, 'Los datos de la fapiao digitalizada se describen explícitamente como la base para un futuro "formulario integrado único" precumplimentado para la declaración de impuestos — una dirección que vale la pena vigilar si opera en China a largo plazo.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '📊 Vorausgefüllte Steuererklärungen in Sicht', NULL, NULL, 'Die digitalisierten Fapiao-Daten werden ausdrücklich als Grundlage für ein künftiges vorausgefülltes "integriertes Einheitsformular" für die Steuererklärung beschrieben — eine Entwicklung, die es zu beobachten lohnt, wenn Sie langfristig in China tätig sind.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '📊 Des déclarations fiscales pré-remplies à l''horizon', NULL, NULL, 'Les données de la fapiao numérisée sont explicitement décrites comme posant les bases d''un futur « formulaire intégré unique » pré-rempli pour la déclaration fiscale — une évolution à surveiller si vous opérez en Chine à long terme.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'China' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure su cuenta fiscal digital', 'Esta es su interfaz continua con la plataforma nacional de servicios de facturación electrónica — para consulta, descarga y seguimiento de sus e-fapiao emitidas y recibidas.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie Ihr digitales Steuerkonto ein', 'Dies ist Ihre fortlaufende Schnittstelle zur nationalen E-Invoicing-Dienstplattform — zur Abfrage, zum Herunterladen und zur Nachverfolgung Ihrer ausgestellten und empfangenen E-Fapiao.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place votre compte fiscal numérique', 'Il s''agit de votre interface continue avec la plateforme nationale de services de facturation électronique — pour la consultation, le téléchargement et le suivi de vos e-fapiao émises et reçues.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme un software de facturación aprobado por la STA', 'Su sistema de facturación necesita generar XML estructurado conforme — verifique que el módulo de e-fapiao de su ERP o plataforma de facturación está actualizado según las especificaciones de la STA.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie STA-zugelassene Rechnungssoftware', 'Ihr Rechnungssystem muss konformes strukturiertes XML erzeugen — überprüfen Sie, ob das E-Fapiao-Modul Ihres ERP- oder Abrechnungssystems den STA-Spezifikationen entspricht.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez un logiciel de facturation approuvé par la STA', 'Votre système de facturation doit générer du XML structuré conforme — vérifiez que le module e-fapiao de votre ERP ou plateforme de facturation est à jour par rapport aux spécifications de la STA.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Comprenda su cuota de facturación', 'Compruebe qué cuota se ha asignado a su empresa y qué factores (nivel de riesgo fiscal, calificación crediticia, operaciones comerciales) la determinan — vale la pena gestionarla activamente, no solo vigilarla.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Verstehen Sie Ihr Rechnungskontingent', 'Prüfen Sie, welches Kontingent Ihrem Unternehmen zugewiesen wurde und welche Faktoren (Steuerrisikostufe, Kreditbewertung, Geschäftstätigkeit) es bestimmen — dies lohnt sich aktiv zu managen, nicht nur zu beobachten.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Comprenez votre quota de facturation', 'Vérifiez quel quota a été attribué à votre entreprise et quels facteurs (niveau de risque fiscal, cote de crédit, activité commerciale) le déterminent — cela mérite une gestion active, pas seulement une simple surveillance.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija sus canales de entrega', 'Decida cómo entregará las facturas a los destinatarios — cuenta fiscal digital, correo electrónico, enlace de plataforma o código QR — ya que la e-fapiao totalmente digitalizada no impone un único método fijo.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie Ihre Zustellkanäle', 'Entscheiden Sie, wie Sie Rechnungen an Empfänger zustellen — digitales Steuerkonto, E-Mail, Plattformlink oder QR-Code — da vollständig digitalisierte E-Fapiao keine einzige feste Methode vorschreibt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez vos canaux de livraison', 'Décidez comment vous livrerez les factures aux destinataires — compte fiscal numérique, e-mail, lien de plateforme ou code QR — la e-fapiao entièrement numérisée n''imposant pas de méthode fixe unique.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure un archivo escalonado', 'Confirme qué categorías de comprobantes requieren 10 años de conservación frente al nivel extendido de 30 años, y construya su sistema de archivo en torno al XML compensado más el código QR, el código de factura y la firma digital asociados.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie eine gestaffelte Archivierung ein', 'Bestätigen Sie, welche Ihrer Belegkategorien 10 Jahre Aufbewahrung erfordern und welche die erweiterte 30-Jahres-Stufe, und bauen Sie Ihr Archivierungssystem um das cleared XML plus den zugehörigen QR-Code, Rechnungscode und die digitale Signatur herum auf.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place un archivage échelonné', 'Confirmez quelles catégories de pièces justificatives nécessitent 10 ans de conservation par rapport au niveau étendu de 30 ans, et construisez votre système d''archivage autour du XML contrôlé plus le code QR, le code de facture et la signature numérique associés.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Siga su calendario regional de eliminación del papel', 'Consulte los anuncios específicos de su sucursal local de la STA — la transición fuera del papel se está produciendo región por región y sector por sector, no en una fecha nacional uniforme.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Verfolgen Sie Ihren regionalen Zeitplan für den Papierausstieg', 'Prüfen Sie die spezifischen Ankündigungen Ihrer lokalen STA-Niederlassung — der Übergang weg vom Papier erfolgt Region für Region und Sektor für Sektor, nicht an einem einheitlichen landesweiten Termin.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Suivez votre calendrier régional d''abandon du papier', 'Consultez les annonces spécifiques de votre antenne locale de la STA — la transition hors du papier se fait région par région et secteur par secteur, et non à une date nationale uniforme.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'China' AND ds.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Administración Estatal de Impuestos (STA)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'China' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'Staatliche Steuerverwaltung (STA)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'China' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'Administration fiscale d''État (STA)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'China' AND dp.sort_order = 0;
